## Code Example
```javascript
// Pseudocode: bounded mailbox in a tiny OS
class Mailbox {
  constructor(cap) {
    this.buf = new Array(cap);
    this.head = 0; this.tail = 0; this.count = 0; this.cap = cap;
    this.lock = new Mutex();
    this.notEmpty = new CondVar();
    this.notFull = new CondVar();
  }
}

function trySend(mb, m) {
  mb.lock.lock();
  if (mb.count === mb.cap) { mb.lock.unlock(); return false; }
  mb.buf[mb.tail] = m;
  mb.tail = (mb.tail + 1) % mb.cap;
  mb.count++;
  mb.notEmpty.signal();
  mb.lock.unlock();
  return true;
}

function blockingRecv(mb, out) {
  mb.lock.lock();
  while (mb.count === 0) {
    mb.notEmpty.wait(mb.lock);
  }
  *out = mb.buf[mb.head];
  mb.head = (mb.head + 1) % mb.cap;
  mb.count--;
  mb.notFull.signal();
  mb.lock.unlock();
}
```

## Why This Is Asked

Multi-tenant I/O contention tests practical OS scheduling design, fairness guarantees, and real workload handling on a block device.

## Key Concepts

- per-tenant queues
- credit-based throttling
- burst handling
- fairness metrics

## Code Example

```javascript
// Minimal sketch: enqueue/dequeue with per-tenant credits (pseudo-C)
class TenantQueue {
  constructor(creditLimit) {
    this.credits = creditLimit;
    this.queue = [];
  }
  enqueue(req) { this.queue.push(req); }
  dequeue() { return this.queue.shift(); }
}
function chooseNext(tenants) {
  // pick queue with max deficit ratio: (creditUsed / max(credit,1))
  let best = null; let bestScore = -Infinity;
  for (const t of tenants) {
    const score = t.credits <= 0 ? -Infinity : 1 - t.credits / t.creditLimit;
    if (score > bestScore) { bestScore = score; best = t; }
  }
  return best && best.queue.length ? best.dequeue() : null;
}
```

